<?php
if(!defined('ABSPATH')){exit;}
final class SPF_Login_Branding {
 const OPTION='spf_brand_login';
 public function hooks(){if(get_option(self::OPTION,'0')!=='1'){return;}add_action('login_enqueue_scripts',[$this,'assets']);add_filter('login_headerurl',[$this,'header_url']);add_filter('login_headertext',[$this,'header_text']);}
 public function assets(){?><style>body.login{background:#f4f7fb;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}body.login #login{width:390px;max-width:calc(100% - 32px);padding-top:9vh}body.login h1 a{background-image:none!important;background:linear-gradient(135deg,#1d4ed8 0%,#5b8cff 100%);color:#fff!important;width:auto;height:auto;min-height:0;padding:22px 26px;margin:0 0 22px;border-radius:24px;box-shadow:0 18px 45px rgba(37,99,235,.22);font-size:30px;font-weight:900;line-height:1.1;text-indent:0;text-decoration:none;display:block;letter-spacing:-.035em}body.login form{border:1px solid #dbe4f3;border-radius:22px;box-shadow:0 22px 60px rgba(15,23,42,.10);padding:28px}body.login label{color:#334155;font-weight:700}body.login input[type=text],body.login input[type=password],body.login input[type=email]{border-radius:14px;border-color:#c8d4e8;min-height:46px}body.login .button-primary{background:#2f5be8;border-color:#2f5be8;border-radius:12px;min-height:44px;padding:0 22px;font-weight:800;box-shadow:0 12px 30px rgba(47,91,232,.24)}body.login .button-primary:hover,body.login .button-primary:focus{background:#1d4ed8;border-color:#1d4ed8}body.login #nav,body.login #backtoblog{text-align:center}@media(max-width:480px){body.login #login{padding-top:7vh}body.login h1 a{font-size:26px;border-radius:20px;padding:20px 22px}body.login form{padding:24px}}</style><?php }
 public function header_url(){ $page=absint(get_option('spf_home_page_id',0)); return $page&&get_post_status($page)?get_permalink($page):home_url('/'); }
 public function header_text(){return __('Sistema para Farmacias','sistema-para-farmacias');}
}
